import React, { useEffect, useState } from "react";
import axios from "axios";

const ViewApplications = () => {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editedReasons, setEditedReasons] = useState({});

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        alert("Please login first");
        return;
      }

      const response = await axios.get(
        "http://127.0.0.1:8000/VJISS/view_applications",
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      setApplications(response.data);
    } catch (error) {
      console.error("Error fetching applications:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleReasonChange = (id, value) => {
    setEditedReasons((prev) => ({
      ...prev,
      [id]: value,
    }));
  };

  if (loading) return <p className="p-6">Loading applications...</p>;

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">My Internship Applications</h2>

      {applications.length === 0 ? (
        <p>No applications found.</p>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full border border-gray-300">
            <thead className="bg-gray-100">
              <tr>
                <th className="border p-2">ID</th>
                <th className="border p-2">Name</th>
                <th className="border p-2">Email</th>
                <th className="border p-2">Phone</th>
                <th className="border p-2">Education</th>
                <th className="border p-2">Internship</th>
                <th className="border p-2">Reason</th>
                <th className="border p-2">Status</th>
                <th className="border p-2">Applied On</th>
                <th className="border p-2">Resume</th>
              </tr>
            </thead>

            <tbody>
              {applications.map((app) => (
                <tr key={app.application_id} className="hover:bg-gray-50">
                  <td className="border p-2">{app.application_id}</td>

                  <td className="border p-2">
                    {app.first_name} {app.last_name}
                  </td>

                  <td className="border p-2">{app.email}</td>

                  <td className="border p-2">{app.phone_number}</td>

                  <td className="border p-2">{app.education}</td>

                  <td className="border p-2">
                    {app.internship_offers?.internship_name || "—"}
                  </td>

                  {/* ✅ Reason Textarea */}
                  <td className="border p-2">
                    <textarea
                      rows={2}
                      className="w-full border rounded p-1"
                      value={
                        editedReasons[app.application_id] ??
                        app.reason ??
                        ""
                      }
                      onChange={(e) =>
                        handleReasonChange(
                          app.application_id,
                          e.target.value
                        )
                      }
                      placeholder="Enter reason"
                    />
                  </td>

                  {/* ✅ Status */}
                  <td
                    className={`border p-2 font-semibold ${
                      app.status === "Approved"
                        ? "text-green-600"
                        : app.status === "Rejected"
                        ? "text-red-600"
                        : "text-yellow-600"
                    }`}
                  >
                    {app.status || "Pending"}
                  </td>

                  {/* ✅ Applied On */}
                  <td className="border p-2">
                    {app.applied_on
                      ? new Date(app.applied_on).toLocaleDateString()
                      : "—"}
                  </td>

                  <td className="border p-2">
                    {app.resume ? (
                      <a
                        href={app.resume}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-blue-600 underline"
                      >
                        View Resume
                      </a>
                    ) : (
                      "—"
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default ViewApplications;
